// N+1 scenarios: one success + one per-transport failure + guard toggles.
// 2 single-failure scenarios (one per transport executor).
// Full failure scenarios require per-transport failure mocks (Tier 0 infra).
//
// Guard branch: 'execute_transport_extdeps_gunbc_shell_Codegen_Check'.request (type: TransportRequest)
//   fed by: prepare_transport_extdeps_gunbc_shell_Codegen_Check.request
//   upstream is pure — needs per-node isolation (Tier 1) for full test
//
// Guard branch: 'execute_transport_extdeps_gunbc_shell_Codegen_Run'.request (type: TransportRequest)
//   fed by: prepare_transport_extdeps_gunbc_shell_Codegen_Run.request
//   upstream is pure — needs per-node isolation (Tier 1) for full test
//

/// Happy path: all transports succeed.
